    #[test]
    fn pre_turn_summary_event_matches_the_applied_state_mutation() {
        let mut state = create_test_state();
        state.max_turn_input_tokens = 20_000;
        state.pinned_tool_schema_tokens = 17;
        for index in 0..8 {
            state.messages.push(json!({
                "role": "user",
                "content": format!("问题 {index}: {}", "context ".repeat(80))
            }));
            state.messages.push(json!({
                "role": "assistant",
                "content": format!("answer {index}: {}", "detail ".repeat(80))
            }));
        }
        let admitted_messages = state.messages.clone();
        let admitted_root = astra_turn_types::canonical_conversation_root(&admitted_messages);
        state.initialize_canonical_rewrite_proof(&admitted_messages, &admitted_root, 0);
        let messages_before = state.messages.len();
        let tokens_before = crate::turn::agentic_loop::lifecycle::estimate_context_pressure(
            &state.messages,
            state.pinned_tool_schema_tokens as usize,
            state.max_turn_input_tokens,
        )
        .1;

        let spill_count = pre_turn_summary_spill_count(&state.messages);
        let event = apply_pre_turn_summary(
            &mut state,
            0.82,
            "Preserve the structured facts and continue.".to_string(),
            spill_count,
        )
        .expect("summary must reduce the spilled prefix");
        let tokens_after = crate::turn::agentic_loop::lifecycle::estimate_context_pressure(
            &state.messages,
            state.pinned_tool_schema_tokens as usize,
            state.max_turn_input_tokens,
        )
        .1;

        assert_eq!(event.kind, CompactionKind::PreTurnSummary);
        assert_eq!(event.tokens_before, tokens_before);
        assert_eq!(event.tokens_after, tokens_after);
        assert_eq!(event.tokens_freed, tokens_before - tokens_after);
        assert_eq!(
            event.messages_removed,
            messages_before - state.messages.len()
        );
        assert_eq!(event.messages_after, state.messages.len());
        assert_eq!(state.compact_tier_applied, CompactionTier::CompactHistory);
        assert!(state.context_compression_triggered);

        let (mode, packs) = crate::turn::canonical_commit::canonical_commit_delta(
            &admitted_messages,
            true,
            &state.messages,
            state.canonical_rewrite_proof(),
            false,
        )
        .expect("pre-turn compaction must produce a canonical replacement")
        .expect("pre-turn compaction must remain committable");
        assert_eq!(mode, astra_turn_types::CanonicalDeltaModeV1::Replace);
        assert!(!packs.is_empty());
    }

    #[test]
    fn pre_turn_summary_does_not_rewrite_an_entirely_protected_active_turn() {
        let mut state = create_test_state();
        state.max_turn_input_tokens = 20_000;
        state.messages = vec![json!({"role": "user", "content": "long active work"})];
        for index in 0..12 {
            state.messages.push(json!({
                "role": "assistant",
                "content": format!("evidence {index}: {}", "detail ".repeat(40)),
            }));
        }
        let mut authority = json!({"role": "user", "content": "continue active Work"});
        astra_turn_types::mark_append_only_required_context(
            &mut authority,
            "active_work_attempt_start",
            astra_turn_types::RuntimeAuthorityLifetime::CurrentUserTurn,
        );
        state.messages.push(authority);
        let before = state.messages.clone();

        let spill_count = pre_turn_summary_spill_count(&state.messages);
        assert_eq!(spill_count, 0);
        assert!(
            apply_pre_turn_summary(&mut state, 0.95, "summary".to_string(), spill_count).is_none()
        );
        assert_eq!(state.messages, before);
        assert_eq!(state.compact_tier_applied, CompactionTier::Normal);
        assert!(!state.context_compression_triggered);
    }

    #[test]
    fn pre_turn_summary_rejects_a_summary_that_does_not_reduce_tokens() {
        let mut state = create_test_state();
        state.max_turn_input_tokens = 20_000;
        for index in 0..12 {
            state.messages.push(json!({
                "role": if index % 2 == 0 { "user" } else { "assistant" },
                "content": format!("short {index}"),
            }));
        }
        let before = state.messages.clone();
        let spill_count = pre_turn_summary_spill_count(&state.messages);
        assert!(spill_count > 0);

        assert!(
            apply_pre_turn_summary(&mut state, 0.9, "oversized ".repeat(2_000), spill_count,)
                .is_none()
        );
        assert_eq!(state.messages, before);
        assert_eq!(state.compact_tier_applied, CompactionTier::Normal);
        assert!(!state.context_compression_triggered);
    }

