    #[cfg(feature = "e2e-hooks")]
    #[tokio::test(flavor = "current_thread")]
    async fn mock_terminal_handoff_keeps_reasoning_private_and_skips_tool_delivery() {
        let public_name = "mcp__provider__arbitrary_control_name";
        let metadata = json!({
            "control": {
                "kind": "moi.control.handoff.v1",
                "target": "agent_authoring",
                "terminal": true,
                "policy_id": "authoring.handoff.v1",
                "ui_visibility": "hidden"
            }
        });
        let descriptor =
            crate::turn::terminal_control::RuntimeControlToolDescriptor::from_metadata(
                public_name,
                Some(&metadata),
            )
            .expect("valid control metadata")
            .expect("control descriptor");
        let snapshot =
            crate::turn::terminal_control::RuntimeControlToolSnapshot::new(vec![descriptor]);
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "user-handoff".to_string(),
            "".to_string(),
        )
        .with_edge_tools(sample_edge_tools())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .with_test_llm_rounds(vec![json!({
            "reasoning": "private routing analysis",
            "tool_calls": [{
                "id": "call-handoff",
                "type": "function",
                "function": {
                    "name": public_name,
                    "arguments": r#"{"action":"revise_current_agent"}"#
                }
            }],
            "usage": {"prompt_tokens": 13, "completion_tokens": 3}
        })])
        .build();
        host.install_runtime_tool_schemas(
            vec![json!({
                "type": "function",
                "function": {
                    "name": public_name,
                    "description": "Transfer runtime control",
                    "parameters": {
                        "type": "object",
                        "properties": {"action": {"type": "string"}},
                        "required": ["action"]
                    }
                }
            })],
            snapshot,
        );
        let mut state = create_test_state();
        state.message = "revise the current agent".to_string();
        state.user_intent = state.message.clone();

        let result = host
            .run_one_mock_turn_for_test(&mut state)
            .await
            .expect("mock terminal handoff turn");
        let events = host.take_emitted_events();

        assert!(result.edge_tool_round.is_empty());
        assert!(events.iter().any(|event| {
            event.get("type").and_then(Value::as_str) == Some("runtime.control.handoff.requested")
        }));
        assert!(events.iter().all(|event| {
            !matches!(
                event.get("type").and_then(Value::as_str),
                Some("reasoning_delta" | "reasoning_done" | "text_delta" | "tool_call")
            )
        }));
        assert!(matches!(
            host.take_terminal_control_outcome(),
            Some(crate::turn::terminal_control::TerminalControlOutcome::Requested(_))
        ));
    }

    #[cfg(feature = "e2e-hooks")]
    #[tokio::test(flavor = "current_thread")]
    async fn idless_terminal_handoff_is_rejected_before_control_or_delivery() {
        let public_name = "mcp__provider__runtime_control";
        let descriptor =
            crate::turn::terminal_control::RuntimeControlToolDescriptor::from_metadata(
                public_name,
                Some(&json!({
                    "control": {
                        "kind": "moi.control.handoff.v1",
                        "target": "agent_authoring",
                        "terminal": true,
                        "policy_id": "authoring.handoff.v1"
                    }
                })),
            )
            .expect("valid control metadata")
            .expect("control descriptor");
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "user-idless-handoff".to_string(),
            "".to_string(),
        )
        .with_edge_tools(sample_edge_tools())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .with_test_llm_rounds(vec![json!({
            "tool_calls": [{
                "type": "function",
                "function": {
                    "name": public_name,
                    "arguments": r#"{"action":"revise_current_agent"}"#
                }
            }],
            "usage": {"prompt_tokens": 8, "completion_tokens": 3}
        })])
        .build();
        host.install_runtime_tool_schemas(
            vec![json!({
                "type": "function",
                "function": {
                    "name": public_name,
                    "description": "Transfer runtime control",
                    "parameters": {"type": "object", "properties": {}}
                }
            })],
            crate::turn::terminal_control::RuntimeControlToolSnapshot::new(vec![descriptor]),
        );
        let mut state = create_test_state();
        let result = host
            .run_one_mock_turn_for_test(&mut state)
            .await
            .expect("mock terminal turn");
        assert!(
            result.edge_tool_round.is_empty(),
            "terminal control must not produce an ordinary edge-tool result"
        );

        let admission = AgenticLoopHost::admit_tool_calls(
            &mut host,
            &result.accum.tool_calls,
            Some("tool_calls"),
        );
        assert!(admission.admitted.is_empty());
        assert_eq!(admission.rejected.len(), 1);
        assert!(host.take_terminal_control_outcome().is_none());

        let delivered = host
            .handle_admitted_tool_calls(&state, &admission.admitted)
            .await;
        assert!(delivered.results.is_empty());
        assert_eq!(delivered.control, AdmittedToolCallControl::Continue);
        assert!(host.edge_callback_ledger.lock().await.is_empty());
    }

    #[tokio::test(flavor = "current_thread")]
    #[serial_test::serial(auxiliary_llm_capacity_policy_env)]
    async fn text_first_control_window_streams_before_provider_completion() {
        let _provider_admission = EnvVarGuard::remove("ASTRA_LLM_PROVIDER_ADMISSION_MODE");
        let session_id = "session-stream-window";
        let inference_ledger = crate::turn::llm::durable::TestInferenceLedgerPersistence::default();
        let delay = Duration::from_millis(750);
        let (gateway_url, provider_completed, server) = spawn_delayed_streaming_gateway(
            delay,
            vec![
                json!({"choices":[{"delta":{"reasoning_content":"private preface"}}]}),
                json!({"choices":[{"delta":{"content":"visible first"}}]}),
            ],
            vec![
                json!({"choices":[{"delta":{"content":" tail"}}]}),
                json!({
                    "choices":[{"delta":{},"finish_reason":"stop"}],
                    "usage":{"prompt_tokens":8,"completion_tokens":4}
                }),
            ],
        )
        .await;
        let public_name = "mcp__provider__runtime_control";
        let descriptor =
            crate::turn::terminal_control::RuntimeControlToolDescriptor::from_metadata(
                public_name,
                Some(&json!({
                    "control": {
                        "kind": "moi.control.handoff.v1",
                        "target": "agent_authoring",
                        "terminal": true,
                        "policy_id": "authoring.handoff.v1"
                    }
                })),
            )
            .expect("valid control metadata")
            .expect("control descriptor");
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "user-stream-window".to_string(),
            session_id.to_string(),
        )
        .with_edge_tools(sample_edge_tools())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .with_test_inference_ledger(inference_ledger.clone())
        .with_admitted_model_execution(Some(test_gateway_execution(gateway_url, Some(3000))))
        .build();
        host.install_runtime_tool_schemas(
            vec![json!({
                "type": "function",
                "function": {
                    "name": public_name,
                    "description": "Transfer runtime control",
                    "parameters": {"type": "object", "properties": {}}
                }
            })],
            crate::turn::terminal_control::RuntimeControlToolSnapshot::new(vec![descriptor]),
        );
        let (tx, mut rx) = tokio::sync::mpsc::channel(32);
        host.set_event_tx(tx);
        let mut state = create_durable_execution_test_state(session_id);
        state.message = "answer normally".to_string();
        state.user_intent = state.message.clone();

        let observe_first_text = async {
            let mut visible_order = Vec::new();
            let mut saw_llm_call_started = false;
            loop {
                let event = tokio::time::timeout(Duration::from_millis(500), rx.recv())
                    .await
                    .expect("text delta must arrive before delayed provider completion")
                    .expect("event channel remains open");
                let event_type = event
                    .get("type")
                    .and_then(Value::as_str)
                    .unwrap_or_default();
                if event_type == "agent_progress"
                    && event.get("status").and_then(Value::as_str) == Some("llm_call_started")
                {
                    assert!(
                        !provider_completed.load(Ordering::SeqCst),
                        "LLM start waited for provider response completion"
                    );
                    saw_llm_call_started = true;
                }
                if matches!(event_type, "reasoning_delta" | "text_delta") {
                    visible_order.push(event_type.to_string());
                }
                if event_type == "text_delta" {
                    assert_eq!(event["content"].as_str(), Some("visible first"));
                    assert!(
                        saw_llm_call_started,
                        "visible provider output arrived before the LLM start lifecycle event"
                    );
                    assert!(
                        !provider_completed.load(Ordering::SeqCst),
                        "text-first control window waited for the full provider response"
                    );
                    break visible_order;
                }
            }
        };

        let (result, visible_order) =
            tokio::join!(host.execute_turn(&mut state), observe_first_text);
        let result = result.expect("text-first turn");
        assert_eq!(visible_order, vec!["reasoning_delta", "text_delta"]);
        assert_eq!(result.accum.full_text, "visible first tail");
        assert!(provider_completed.load(Ordering::SeqCst));
        assert!(matches!(
            host.take_terminal_control_outcome(),
            None | Some(crate::turn::terminal_control::TerminalControlOutcome::Passthrough)
        ));
        assert_root_llm_progress_pairs(&host.take_emitted_events(), 1);
        inference_ledger.assert_quiescent();
        server.abort();
    }

    #[tokio::test(flavor = "current_thread")]
    #[serial_test::serial(auxiliary_llm_capacity_policy_env)]
    async fn provisional_work_admission_keeps_reasoning_preview_live() {
        let _provider_admission = EnvVarGuard::remove("ASTRA_LLM_PROVIDER_ADMISSION_MODE");
        let session_id = "session-work-admission-reasoning";
        let inference_ledger = crate::turn::llm::durable::TestInferenceLedgerPersistence::default();
        let delay = Duration::from_millis(750);
        let (gateway_url, provider_completed, server) = spawn_delayed_streaming_gateway(
            delay,
            vec![json!({"choices":[{"delta":{"reasoning_content":"live work analysis"}}]})],
            vec![
                json!({"choices":[{"delta":{"content":"final answer"}}]}),
                json!({
                    "choices":[{"delta":{},"finish_reason":"stop"}],
                    "usage":{"prompt_tokens":8,"completion_tokens":4}
                }),
            ],
        )
        .await;
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "user-work-preview".to_string(),
            session_id.to_string(),
        )
        .with_test_inference_ledger(inference_ledger.clone())
        .with_admitted_model_execution(Some(test_gateway_execution(gateway_url, Some(3000))))
        .build();
        host.pending_work_admission_judge = Some(tokio::spawn(async {
            tokio::time::sleep(Duration::from_millis(1_500)).await;
            Err(astra_services::TurnIntentJudgeError::Transport(
                "unused test decision".to_string(),
            ))
        }));
        let (tx, mut rx) = tokio::sync::mpsc::channel(32);
        host.set_event_tx(tx);
        let mut state = create_durable_execution_test_state(session_id);
        state.message = "continue the task".to_string();
        state.user_intent = state.message.clone();

        let observe_reasoning = async {
            loop {
                let event = tokio::time::timeout(Duration::from_millis(500), rx.recv())
                    .await
                    .expect("reasoning preview must arrive during provider inference")
                    .expect("event channel remains open");
                if event.get("type").and_then(Value::as_str) == Some("reasoning_delta") {
                    assert_eq!(event["content"].as_str(), Some("live work analysis"));
                    assert!(
                        !provider_completed.load(Ordering::SeqCst),
                        "Work admission buffered reasoning until provider completion"
                    );
                    break;
                }
            }
        };

        let (result, ()) = tokio::join!(host.execute_turn(&mut state), observe_reasoning);
        result.expect("provisional Work turn");
        inference_ledger.assert_quiescent();
        server.abort();
    }

    #[tokio::test(flavor = "current_thread")]
    #[serial_test::serial(auxiliary_llm_capacity_policy_env)]
    async fn ordinary_tool_first_closes_control_window_before_provider_completion() {
        let _provider_admission = EnvVarGuard::remove("ASTRA_LLM_PROVIDER_ADMISSION_MODE");
        let session_id = "session-tool-window";
        let inference_ledger = crate::turn::llm::durable::TestInferenceLedgerPersistence::default();
        let ordinary_tool = "mcp__provider__status";
        let terminal_tool = "mcp__provider__runtime_control";
        let delay = Duration::from_millis(750);
        let (gateway_url, provider_completed, server) = spawn_delayed_streaming_gateway(
            delay,
            vec![
                json!({"choices":[{"delta":{"reasoning_content":"ordinary tool reasoning"}}]}),
                json!({
                    "choices":[{"delta":{"tool_calls":[{
                        "index":0,
                        "id":"call-status",
                        "type":"function",
                        "function":{"name":ordinary_tool,"arguments":"{}"}
                    }]}}]
                }),
            ],
            vec![json!({
                "choices":[{"delta":{},"finish_reason":"tool_calls"}],
                "usage":{"prompt_tokens":8,"completion_tokens":4}
            })],
        )
        .await;
        let descriptor =
            crate::turn::terminal_control::RuntimeControlToolDescriptor::from_metadata(
                terminal_tool,
                Some(&json!({
                    "control": {
                        "kind": "moi.control.handoff.v1",
                        "target": "agent_authoring",
                        "terminal": true,
                        "policy_id": "authoring.handoff.v1"
                    }
                })),
            )
            .expect("valid control metadata")
            .expect("control descriptor");
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "user-tool-window".to_string(),
            session_id.to_string(),
        )
        .with_edge_tools(sample_edge_tools())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .with_test_inference_ledger(inference_ledger.clone())
        .with_admitted_model_execution(Some(test_gateway_execution(gateway_url, Some(3000))))
        .build();
        host.install_runtime_tool_schemas(
            vec![
                json!({
                    "type": "function",
                    "function": {
                        "name": ordinary_tool,
                        "description": "Read provider status",
                        "parameters": {"type": "object", "properties": {}}
                    }
                }),
                json!({
                    "type": "function",
                    "function": {
                        "name": terminal_tool,
                        "description": "Transfer runtime control",
                        "parameters": {"type": "object", "properties": {}}
                    }
                }),
            ],
            crate::turn::terminal_control::RuntimeControlToolSnapshot::new(vec![descriptor]),
        );
        let (tx, mut rx) = tokio::sync::mpsc::channel(32);
        host.set_event_tx(tx);
        let mut state = create_durable_execution_test_state(session_id);
        state.message = "check status".to_string();
        state.user_intent = state.message.clone();

        let observe_reasoning_release = async {
            loop {
                let event = tokio::time::timeout(Duration::from_millis(500), rx.recv())
                    .await
                    .expect("ordinary tool must release buffered reasoning before completion")
                    .expect("event channel remains open");
                if event.get("type").and_then(Value::as_str) == Some("reasoning_delta") {
                    assert_eq!(event["content"].as_str(), Some("ordinary tool reasoning"));
                    assert!(
                        !provider_completed.load(Ordering::SeqCst),
                        "ordinary tool action waited for the full provider response"
                    );
                    break;
                }
            }
        };

        let (result, ()) = tokio::join!(host.execute_turn(&mut state), observe_reasoning_release);
        let result = result.expect("ordinary tool-first turn");
        assert_eq!(result.accum.tool_calls.len(), 1);
        assert_eq!(
            result.accum.tool_calls[0]["function"]["name"].as_str(),
            Some(ordinary_tool)
        );
        assert!(provider_completed.load(Ordering::SeqCst));
        assert!(host.take_terminal_control_outcome().is_none());
        inference_ledger.assert_quiescent();
        server.abort();
    }

    #[tokio::test(flavor = "current_thread")]
    #[serial_test::serial(auxiliary_llm_capacity_policy_env)]
    async fn streamed_terminal_handoff_never_projects_buffered_reasoning() {
        let _provider_admission = EnvVarGuard::remove("ASTRA_LLM_PROVIDER_ADMISSION_MODE");
        let session_id = "session-terminal-stream";
        let inference_ledger = crate::turn::llm::durable::TestInferenceLedgerPersistence::default();
        let terminal_tool = "mcp__provider__runtime_control";
        let (gateway_url, provider_completed, server) = spawn_delayed_streaming_gateway(
            Duration::from_millis(200),
            vec![
                json!({"choices":[{"delta":{"reasoning_content":"private handoff reasoning"}}]}),
                json!({
                    "choices":[{"delta":{"tool_calls":[{
                        "index":0,
                        "id":"call-handoff",
                        "type":"function",
                        "function":{
                            "name":terminal_tool,
                            "arguments":r#"{"action":"revise_current_agent"}"#
                        }
                    }]}}]
                }),
            ],
            vec![json!({
                "choices":[{"delta":{},"finish_reason":"tool_calls"}],
                "usage":{"prompt_tokens":8,"completion_tokens":4}
            })],
        )
        .await;
        let descriptor =
            crate::turn::terminal_control::RuntimeControlToolDescriptor::from_metadata(
                terminal_tool,
                Some(&json!({
                    "control": {
                        "kind": "moi.control.handoff.v1",
                        "target": "agent_authoring",
                        "terminal": true,
                        "policy_id": "authoring.handoff.v1"
                    }
                })),
            )
            .expect("valid control metadata")
            .expect("control descriptor");
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "user-terminal-stream".to_string(),
            session_id.to_string(),
        )
        .with_edge_tools(sample_edge_tools())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .with_test_inference_ledger(inference_ledger.clone())
        .with_admitted_model_execution(Some(test_gateway_execution(gateway_url, Some(3000))))
        .build();
        host.install_runtime_tool_schemas(
            vec![json!({
                "type": "function",
                "function": {
                    "name": terminal_tool,
                    "description": "Transfer runtime control",
                    "parameters": {
                        "type": "object",
                        "properties": {"action": {"type": "string"}},
                        "required": ["action"]
                    }
                }
            })],
            crate::turn::terminal_control::RuntimeControlToolSnapshot::new(vec![descriptor]),
        );
        let (tx, mut rx) = tokio::sync::mpsc::channel(32);
        host.set_event_tx(tx);
        let mut state = create_durable_execution_test_state(session_id);
        state.message = "revise the agent".to_string();
        state.user_intent = state.message.clone();

        let result = host.execute_turn(&mut state).await.expect("terminal turn");
        assert!(result.edge_tool_round.is_empty());
        assert!(provider_completed.load(Ordering::SeqCst));
        let mut streamed_events = Vec::new();
        while let Ok(event) = rx.try_recv() {
            streamed_events.push(event);
        }
        assert!(streamed_events.iter().any(|event| {
            event.get("type").and_then(Value::as_str) == Some("runtime.control.handoff.requested")
        }));
        assert!(streamed_events.iter().all(|event| {
            !matches!(
                event.get("type").and_then(Value::as_str),
                Some("reasoning_delta" | "reasoning_done" | "text_delta" | "tool_call")
            )
        }));
        assert!(matches!(
            host.take_terminal_control_outcome(),
            Some(crate::turn::terminal_control::TerminalControlOutcome::Requested(_))
        ));
        inference_ledger.assert_quiescent();
        server.abort();
    }

    #[tokio::test(flavor = "current_thread")]
    #[serial_test::serial(auxiliary_llm_capacity_policy_env)]
    async fn execute_turn_persists_full_journal_request_and_response_when_session_capture_enabled()
    {
        let _provider_admission = EnvVarGuard::remove("ASTRA_LLM_PROVIDER_ADMISSION_MODE");
        let inference_ledger = crate::turn::llm::durable::TestInferenceLedgerPersistence::default();
        let temp = tempfile::tempdir().unwrap();
        let _guard = astra_services::session_journal::JournalDirGuard::new(temp.path());
        let session_id = "00000000-0000-0000-0000-000000000126";
        let (gateway_url, requests, server) = spawn_gateway(
            axum::http::StatusCode::OK,
            json!({
                "choices": [
                    {
                        "message": { "content": "journal capture reply" },
                        "finish_reason": "stop"
                    }
                ],
                "usage": { "prompt_tokens": 12, "completion_tokens": 5 }
            }),
        )
        .await;

        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "user-journal".to_string(),
            session_id.to_string(),
        )
        .with_edge_tools(sample_edge_tools())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .with_test_inference_ledger(inference_ledger.clone())
        .with_full_llm_capture(true)
        .with_admitted_model_execution(Some(test_gateway_execution(gateway_url, Some(2000))))
        .build();
        let mut state = create_durable_execution_test_state(session_id);
        state.session_turn = 1;
        state.turn_event_buffer =
            Some(astra_services::session_journal::TurnEventBuffer::begin_turn(Some(session_id), 1));
        state
            .messages
            .push(json!({"role": "user", "content": "capture this turn"}));
        state.message = "capture this turn".to_string();
        state.user_intent = state.message.clone();

        host.execute_turn(&mut state).await.expect("execute turn");

        state
            .turn_event_buffer
            .as_mut()
            .expect("turn event buffer")
            .flush(
                &astra_services::session_journal::JournalWriter::for_user(
                    "user-journal",
                    session_id,
                )
                .expect("journal writer"),
            )
            .expect("flush journal");

        let journal = read_journal_events("user-journal", session_id);
        let llm_events: Vec<_> = journal
            .iter()
            .filter(|event| {
                matches!(
                    event.get("type").and_then(Value::as_str),
                    Some("llm_request_full" | "llm_response_full")
                )
            })
            .collect();
        assert_eq!(
            llm_events.len(),
            2,
            "expected request+response events: {journal:?}"
        );
        assert_eq!(
            llm_events[0].get("type").and_then(Value::as_str),
            Some("llm_request_full")
        );
        assert_eq!(
            llm_events[1].get("type").and_then(Value::as_str),
            Some("llm_response_full")
        );
        let captured_request_messages = llm_events[0]["metadata"]["request"]["messages"]
            .as_array()
            .expect("captured request messages");
        let captured_summary_roles = llm_events[0]["metadata"]["request_summary"]["message_roles"]
            .as_array()
            .expect("captured summary roles");
        assert_eq!(
            llm_events[0]["metadata"]["request_summary"]["message_count"].as_u64(),
            Some(captured_request_messages.len() as u64)
        );
        assert_eq!(
            captured_summary_roles.len(),
            captured_request_messages.len()
        );
        assert!(
            captured_request_messages.len() >= 2,
            "expected at least system + user messages"
        );
        assert!(
            llm_events[0]["metadata"]["prompt_request_id"]
                .as_str()
                .is_some_and(|value| !value.is_empty())
        );
        assert_eq!(
            llm_events[0]["metadata"]["request_summary"]["message_roles"][0]["role"].as_str(),
            Some("system")
        );
        assert_eq!(
            captured_summary_roles
                .last()
                .and_then(|entry| entry["role"].as_str()),
            Some("user")
        );
        assert_eq!(
            captured_request_messages
                .last()
                .and_then(|message| message["role"].as_str()),
            Some("user")
        );
        assert_eq!(
            captured_request_messages
                .last()
                .and_then(|message| message["content"].as_str()),
            Some("capture this turn"),
            "the provider boundary must preserve the current user text byte-for-byte"
        );
        for message in captured_request_messages
            .iter()
            .filter(|message| message["role"] == "user")
        {
            let content = message["content"].as_str().unwrap_or_default();
            assert!(!content.contains("Turn Budget"));
            assert!(!content.contains("Capabilities"));
            assert!(!content.contains("Turn-start session execution state"));
            assert!(!content.contains("<system-reminder>"));
        }
        assert_eq!(
            llm_events[1]["metadata"]["response"]["outcome"].as_str(),
            Some("success_stop")
        );
        assert_eq!(
            llm_events[1]["metadata"]["response"]["response"]["finish_reason"].as_str(),
            Some("stop")
        );
        assert_eq!(
            llm_events[1]["metadata"]["response"]["response"]["full_text"].as_str(),
            Some("journal capture reply")
        );
        assert!(
            [
                "Turn Budget",
                "Capabilities",
                "Turn-start session execution state"
            ]
            .iter()
            .all(|fragment| !state.final_text.contains(fragment)),
            "final assistant output must not contain runtime configuration fragments"
        );
        assert_eq!(
            llm_events[1]["metadata"]["response"]["response"]["usage"]["output_tokens"].as_i64(),
            Some(5)
        );
        assert_eq!(
            llm_events[0]["metadata"]["trace"]["session_turn_source"].as_str(),
            Some("state")
        );
        let expected_cache_capability =
            astra_turn_core::cache_placement::CacheCapability::for_provider("openai");
        assert_eq!(
            serde_json::from_value::<astra_turn_core::cache_placement::CacheCapability>(
                llm_events[0]["metadata"]["trace"]["cache_capability"].clone(),
            )
            .unwrap(),
            expected_cache_capability
        );
        assert_eq!(
            llm_events[0]["metadata"]["cache_capability"],
            llm_events[1]["metadata"]["cache_capability"],
            "request and response capture must report the same resolved shape"
        );
        let diagnostic_snapshot =
            astra_turn_core::introspect::cache_diagnosis::snapshot_from_capture_json(
                &llm_events[0]["metadata"],
            );
        assert_eq!(
            diagnostic_snapshot.cache_capability,
            Some(expected_cache_capability),
            "harness/introspect parser must recover exact capability from journal metadata"
        );
        assert!(
            llm_events[0]["metadata"]["trace"]["turn_chain_id"].is_null(),
            "server-loop trace should not fabricate bridge correlation ids"
        );

        let gateway_requests = requests.lock().await;
        assert_eq!(gateway_requests.len(), 1, "one upstream request expected");

        inference_ledger.assert_quiescent();
        server.abort();
    }

    #[tokio::test(flavor = "current_thread")]
    #[serial_test::serial(auxiliary_llm_capacity_policy_env)]
    async fn execute_turn_persists_full_journal_error_response_when_session_capture_enabled() {
        let _provider_admission = EnvVarGuard::remove("ASTRA_LLM_PROVIDER_ADMISSION_MODE");
        let inference_ledger = crate::turn::llm::durable::TestInferenceLedgerPersistence::default();
        // Collapse llm_client's 1s/2s/4s exponential backoff so the retry
        // loop behind a 500 upstream completes in tens of ms instead of 7s.
        let _backoff = crate::turn::llm::client::set_test_retry_backoff_ms(0);
        let temp = tempfile::tempdir().unwrap();
        let _guard = astra_services::session_journal::JournalDirGuard::new(temp.path());
        let session_id = "00000000-0000-0000-0000-000000000127";
        let (gateway_url, requests, server) = spawn_gateway(
            axum::http::StatusCode::INTERNAL_SERVER_ERROR,
            json!({"error": {"message": "upstream exploded"}}),
        )
        .await;

        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "user-journal".to_string(),
            session_id.to_string(),
        )
        .with_edge_tools(sample_edge_tools())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .with_test_inference_ledger(inference_ledger.clone())
        .with_full_llm_capture(true)
        .with_admitted_model_execution(Some(test_gateway_execution(gateway_url, Some(2000))))
        .build();
        let mut state = create_durable_execution_test_state(session_id);
        state.session_turn = 1;
        state.turn_event_buffer =
            Some(astra_services::session_journal::TurnEventBuffer::begin_turn(Some(session_id), 1));
        state
            .messages
            .push(json!({"role": "user", "content": "capture this failed turn"}));
        state.message = "capture this failed turn".to_string();
        state.user_intent = state.message.clone();

        let error = match host.execute_turn(&mut state).await {
            Ok(_) => panic!("execute turn should fail"),
            Err(error) => error,
        };
        assert_eq!(error.kind, astra_core::ErrorKind::ServerError);
        let emitted_events = host.take_emitted_events();
        assert_root_llm_progress_pairs(&emitted_events, 1);
        let phase_outcomes: Vec<_> = emitted_events
            .into_iter()
            .filter(|event| {
                event.get("type").and_then(Value::as_str)
                    == Some(astra_server_types::TURN_PHASE_EVENT_TYPE)
            })
            .map(|event| {
                (
                    event["phase"].as_str().unwrap_or_default().to_string(),
                    event["outcome"].as_str().unwrap_or_default().to_string(),
                )
            })
            .collect();
        assert_eq!(
            phase_outcomes,
            vec![
                ("request_preparation".to_string(), "succeeded".to_string()),
                ("model_inference".to_string(), "failed".to_string()),
            ],
            "a provider failure must retain both the completed pre-provider boundary and the failed model boundary"
        );

        state
            .turn_event_buffer
            .as_mut()
            .expect("turn event buffer")
            .flush(
                &astra_services::session_journal::JournalWriter::for_user(
                    "user-journal",
                    session_id,
                )
                .expect("journal writer"),
            )
            .expect("flush journal");

        let journal = read_journal_events("user-journal", session_id);
        let llm_events: Vec<_> = journal
            .iter()
            .filter(|event| {
                matches!(
                    event.get("type").and_then(Value::as_str),
                    Some("llm_request_full" | "llm_response_full")
                )
            })
            .collect();
        assert_eq!(
            llm_events.len(),
            2,
            "expected request+error events: {journal:?}"
        );
        assert_eq!(
            llm_events[1]["metadata"]["response"]["outcome"].as_str(),
            Some("error")
        );
        assert_eq!(
            llm_events[1]["metadata"]["response"]["response"]["kind"].as_str(),
            Some("server_error")
        );
        assert!(
            llm_events[1]["metadata"]["response"]["response"]["error"]
                .as_str()
                .is_some_and(|message| message.contains("LLM error 500")),
            "expected stored error payload: {}",
            llm_events[1]
        );
        assert_eq!(
            llm_events[1]["metadata"]["trace"]["session_turn_source"].as_str(),
            Some("state")
        );
        assert!(
            requests.lock().await.len() > 1,
            "transport retries must stay inside one LLM lifecycle pair"
        );

        inference_ledger.assert_quiescent();
        server.abort();
    }

