    /// Core invariant: the prompt-visible schema must match the active runtime
    /// tool policy, including skill allowlists.
    #[test]
    fn skill_allowed_tools_do_not_prune_prompt_visible_tools() {
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "u".to_string(),
            "s".to_string(),
        )
        .with_edge_tools(sample_edge_tools_full())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .build();

        let mut state = create_test_state();
        state.session_turn = 1;
        // Simulate: review skill activated with read-only allowed_tools
        state.skills.allowed_tools = Some(
            ["bash", "read_file", "grep"]
                .iter()
                .map(|s| s.to_string())
                .collect(),
        );
        state.skills.invoked.insert(
            "review-changes".into(),
            crate::turn::skill_tool::InvokedSkill {
                name: "review-changes".into(),
                content: String::new(),
                invoked_at_turn: 1,
                reentry_count: 0,
                execution_topology: None,
            },
        );

        let visible = host.visible_turn_tools(&mut state);
        let visible_names: Vec<&str> = visible
            .iter()
            .filter_map(|t| {
                t.get("function")
                    .and_then(|f| f.get("name"))
                    .and_then(Value::as_str)
            })
            .collect();

        assert!(
            visible_names.contains(&"bash"),
            "skill-hinted tool must stay visible"
        );
        assert!(
            visible_names.contains(&"read_file"),
            "skill-hinted tool must stay visible"
        );
        assert!(
            visible_names.contains(&"grep"),
            "skill-hinted tool must stay visible"
        );
        assert!(
            visible_names.contains(&"str_replace"),
            "skill hints must not hide otherwise-callable tools from the prompt-visible schema"
        );
        assert!(
            visible_names.contains(&"write_file"),
            "skill hints must not hide otherwise-callable tools from the prompt-visible schema"
        );
    }

    /// After a skill sets allowed_tools, later turns should keep the same hint
    /// state without turning it into a hard prompt-visible restriction.
    #[test]
    fn skill_allowed_tools_leave_prompt_schemas_unpruned_across_turns() {
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "u".to_string(),
            "s".to_string(),
        )
        .with_edge_tools(sample_edge_tools_full())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .build();

        let mut state = create_test_state();
        // Turn 1: review skill active
        state.session_turn = 1;
        state.skills.allowed_tools = Some(
            ["bash", "read_file", "grep"]
                .iter()
                .map(|s| s.to_string())
                .collect(),
        );
        state.skills.invoked.insert(
            "review-changes".into(),
            crate::turn::skill_tool::InvokedSkill {
                name: "review-changes".into(),
                content: String::new(),
                invoked_at_turn: 1,
                reentry_count: 0,
                execution_topology: None,
            },
        );
        let _turn1 = host.visible_turn_tools(&mut state);

        // Turn 2: the loaded skill hint still governs the session until another
        // activation replaces it, but the full callable schema stays visible.
        state.session_turn = 2;
        let visible = host.visible_turn_tools(&mut state);
        let visible_names: Vec<&str> = visible
            .iter()
            .filter_map(|t| {
                t.get("function")
                    .and_then(|f| f.get("name"))
                    .and_then(Value::as_str)
            })
            .collect();

        assert!(
            visible_names.contains(&"str_replace"),
            "turn 2 should keep the full callable schema visible"
        );
        assert!(
            visible_names.contains(&"write_file"),
            "turn 2 should keep the full callable schema visible"
        );
    }

    /// request_constraints.allowed_tools (from delegation) must still restrict
    /// tools — this is a security boundary for child agents, NOT skill metadata.
    #[test]
    fn request_constraints_still_restrict_tools() {
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "u".to_string(),
            "s".to_string(),
        )
        .with_edge_tools(sample_edge_tools_full())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .build();

        let mut state = create_test_state();
        // Delegation constrains to bash + read_file only
        state.skills.request_constraints.allowed_tools = Some(
            ["bash", "read_file"]
                .iter()
                .map(|s| s.to_string())
                .collect(),
        );
        // No skill allowed_tools set

        let visible = host.visible_turn_tools(&mut state);
        let visible_names: Vec<&str> = visible
            .iter()
            .filter_map(|t| {
                t.get("function")
                    .and_then(|f| f.get("name"))
                    .and_then(Value::as_str)
            })
            .collect();

        assert!(visible_names.contains(&"bash"));
        assert!(visible_names.contains(&"read_file"));
        assert!(
            !visible_names.contains(&"str_replace"),
            "request_constraints must still restrict — this is a delegation security boundary"
        );
        assert!(
            !visible_names.contains(&"write_file"),
            "request_constraints must still restrict — this is a delegation security boundary"
        );
    }

    /// A durable Work binding changes lifecycle state, but it must never
    /// widen a delegated child's explicit capability envelope. This is the
    /// unhappy path behind children that were asked to use a network tool yet
    /// saw only Work-planning tools.
    #[test]
    fn bound_work_projection_does_not_bypass_child_tool_allowlist() {
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "u".to_string(),
            "s".to_string(),
        )
        .with_edge_tools(sample_edge_tools_with_web_fetch())
        .with_execution_binding_snapshot(edge_runtime_snapshot())
        .with_work_planning_bound(true)
        .build();

        let mut state = create_test_state();
        state.skills.request_constraints.allowed_tools =
            Some(["web_fetch".to_string()].into_iter().collect());

        let visible = schema_names(&host.visible_turn_tools(&mut state));
        assert!(
            visible.contains("web_fetch"),
            "the child's explicitly admitted edge capability must survive: {visible:?}"
        );
        for forbidden in [
            "bash",
            "read_file",
            "run_next_work_item",
            "inspect_work_plan",
            "propose_work_plan",
            "inspect_work_criteria",
            "propose_work_criteria",
            "settle_work_item",
        ] {
            assert!(
                !visible.contains(forbidden),
                "bound Work must not widen a child allowlist with {forbidden}: {visible:?}"
            );
        }
    }

    #[tokio::test]
    async fn delegated_edge_ledger_child_can_activate_allowlisted_deferred_builtin() {
        let edge_ledger_snapshot = ExecutionBindingSnapshot::inferred(
            WorkspaceBinding::edge_workspace(
                "CLI workspace",
                "/workspace",
                WorkspaceAuthority::ReadWrite,
            ),
            ExecutorBinding::edge_agent(
                "edge-1",
                "CLI workspace",
                crate::server::tool_transport::ToolTransportKind::EdgeLedger,
                crate::server::tool_transport::ExecutorStatus::Online,
            ),
        );
        let mut host = ServerAgenticLoopHostBuilder::new(
            mock_matrixone(),
            mock_encryptor(),
            "u".to_string(),
            "s".to_string(),
        )
        .with_edge_tools(sample_edge_tools())
        .with_execution_binding_snapshot(edge_ledger_snapshot)
        .build();
        assert!(!schema_names(&host.tool_schemas).contains("web_fetch"));

        host.merge_allowlisted_edge_tool_schemas(&["web_fetch".to_string()]);
        let mut state = create_test_state();
        state.skills.request_constraints.allowed_tools = Some(
            ["web_fetch".to_string(), "tool_search".to_string()]
                .into_iter()
                .collect(),
        );

        let visible = schema_names(&host.visible_turn_tools(&mut state));
        assert!(
            visible.contains("web_fetch"),
            "the allowlisted capability must be immediately callable before prompt-tier pruning: {visible:?}"
        );
        assert!(
            schema_names(&host.deferred_tool_schemas).contains("web_fetch"),
            "the same capability must remain discoverable if the prompt pipeline cache-prunes it"
        );
        let pipeline_visible = host.filtered_runtime_ready_turn_tools(&HashSet::new(), &state);
        let outcome = host
            .run_turn_pipeline(
                &mut state,
                &pipeline_visible,
                "openai",
                "deepseek-v4-flash",
                "Fetch one URL",
            )
            .expect("child context pipeline");
        assert!(
            schema_names(&outcome.tool_schemas).contains("web_fetch"),
            "adaptive context optimization must not prune the child's explicit execution contract"
        );
    }

